    function _taxFee() external view returns (uint8);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x222f737285D0B60d8D4f27fA22cE8884c9F119F8;
    address attacker = address(this);
