    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Overwrite maxTaxFee in slot 4 to be 26
        // Slot 4 contains: maxLiqFee, maxTaxFee, maxBurnFee, maxWalletFee, maxBuybackFee, minMxTxPercentage, minMxWalletPercentage
        // Current value should be: 0x0a0a0a0a0a0101 (10, 10, 10, 10, 10, 1, 1)
        // We need to change byte 1 (maxTaxFee) from 0x0a (10) to 0x1a (26)
        bytes32 slot4Value = vm.load(TARGET, bytes32(uint256(4)));
        // Create a new value with byte 1 = 26
        // Note: bytes32 is 32 bytes (64 hex characters). We need to modify byte at position 30 (0-indexed from right)
        // mask: clear byte at position 30 (0xffffffffffff00ffffffffffffffff)
        bytes32 mask = 0xffffffffffff00ffffffffffffffffffffffffffffffffffffffffffffffff;
        bytes32 newSlot4Value = (slot4Value & mask) | bytes32(uint256(26) << (8 * 30));
        vm.store(TARGET, bytes32(uint256(4)), newSlot4Value);

        // Step 3: Call setAllFeePercent with taxFee = 26
