        targetContract.setAllFeePercent(26, 0, 0, 0, 0);

        // Step 4: Verify the tax fee was set > 25
        uint8 newTaxFee = targetContract._taxFee();
        assertGt(uint256(newTaxFee), 25, "Tax fee should be greater than 25");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
